setup:
MUTATE {
  CREATE CONCEPT ?alice { TYPE "Person" NAME "Alice" }
  CREATE CONCEPT ?bob { TYPE "Person" NAME "Bob" }
  CREATE CONCEPT ?carol { TYPE "Person" NAME "Carol" }
  CREATE CONCEPT ?dave { TYPE "Person" NAME "Dave" }
  CREATE CONCEPT ?sensor { TYPE "Person" NAME "Sensor" }
  CREATE CONCEPT ?brain { TYPE "Person" NAME "Brain" }
  CREATE CONCEPT ?beijing { TYPE "Place" NAME "Beijing" }
  CREATE CONCEPT ?shanghai { TYPE "Place" NAME "Shanghai" }
  CREATE CONCEPT ?berlin { TYPE "Place" NAME "Berlin" }
  CREATE CONCEPT ?austin { TYPE "Place" NAME "Austin" }
  CREATE CONCEPT ?dallas { TYPE "Place" NAME "Dallas" }
  CREATE CONCEPT ?campus { TYPE "Place" NAME "Acme campus" }
  CREATE CONCEPT ?dark { TYPE "ColorScheme" NAME "Dark" }
  CREATE CONCEPT ?light { TYPE "ColorScheme" NAME "Light" }
  CREATE CONCEPT ?vim { TYPE "Editor" NAME "Vim" }
  ENSURE PROPOSITION ?p_bj (?alice, "lives_in", ?beijing)
  ENSURE PROPOSITION ?p_sh (?alice, "lives_in", ?shanghai)
  ENSURE PROPOSITION ?p_be (?carol, "lives_in", ?berlin)
  ENSURE PROPOSITION ?p_dark (?alice, "prefers", ?dark)
  ENSURE PROPOSITION ?p_light (?alice, "prefers", ?light)
  ENSURE PROPOSITION ?p_vim (?alice, "prefers", ?vim)
  ENSURE PROPOSITION ?p_tz8 (?alice, "timezone", "+08:00")
  ENSURE PROPOSITION ?p_tz9 (?alice, "timezone", "+09:00")
  ENSURE PROPOSITION ?p_d1 (?dave, "timezone", "+01:00")
  ENSURE PROPOSITION ?p_d2 (?dave, "timezone", "+02:00")
  ENSURE PROPOSITION ?p_au (?campus, "located_in", ?austin)
  ENSURE PROPOSITION ?p_da (?campus, "located_in", ?dallas)
  CREATE ASSERTION ?a1 { SET FIELDS { proposition: ?p_bj, asserted_by: ?alice, stance: "support", mode: "stated", asserted_at: "2026-01-10T00:00:00.000Z" } }
  CREATE ASSERTION ?a2 { SET FIELDS { proposition: ?p_sh, asserted_by: ?alice, stance: "support", mode: "stated", asserted_at: "2026-09-10T00:00:00.000Z", valid_time: { from: "2026-09-01T00:00:00.000Z" } } }
  CREATE ASSERTION ?a3 { SET FIELDS { proposition: ?p_be, asserted_by: ?carol, stance: "support", mode: "stated", asserted_at: "2026-03-01T00:00:00.000Z", valid_time: { from: { earliest: "2026-01-01T00:00:00.000Z", latest: "2026-12-31T23:59:59.999Z" } } } }
  CREATE ASSERTION ?a4 { SET FIELDS { proposition: ?p_dark, asserted_by: ?alice, stance: "support", mode: "stated", asserted_at: "2026-01-01T00:00:00.000Z", valid_time: { from: "2026-01-01T00:00:00.000Z" } } }
  CREATE ASSERTION ?a5 { SET FIELDS { proposition: ?p_light, asserted_by: ?alice, stance: "support", mode: "stated", asserted_at: "2026-09-01T00:00:00.000Z", valid_time: { from: "2026-09-01T00:00:00.000Z" } } }
  CREATE ASSERTION ?a6 { SET FIELDS { proposition: ?p_vim, asserted_by: ?alice, stance: "support", mode: "stated", asserted_at: "2026-02-01T00:00:00.000Z", valid_time: { from: "2026-02-01T00:00:00.000Z" } } }
  CREATE ASSERTION ?a7 { SET FIELDS { proposition: ?p_tz8, asserted_by: ?alice, stance: "support", mode: "stated", asserted_at: "2026-01-01T00:00:00.000Z" } }
  CREATE ASSERTION ?a8 { SET FIELDS { proposition: ?p_tz9, asserted_by: ?bob, stance: "support", mode: "stated", asserted_at: "2026-09-01T00:00:00.000Z" } }
  CREATE ASSERTION ?a9 { SET FIELDS { proposition: ?p_d1, asserted_by: ?dave, stance: "support", mode: "stated", asserted_at: "2026-01-01T00:00:00.000Z" } }
  CREATE ASSERTION ?a10 { SET FIELDS { proposition: ?p_d2, asserted_by: ?sensor, stance: "support", mode: "observed", asserted_at: "2026-09-05T00:00:00.000Z" } }
  CREATE ASSERTION ?a11 { SET FIELDS { proposition: ?p_au, asserted_by: ?brain, stance: "support", mode: "inferred", asserted_at: "2026-01-10T00:00:00.000Z" } }
  CREATE ASSERTION ?a12 { SET FIELDS { proposition: ?p_da, asserted_by: ?brain, stance: "support", mode: "inferred", asserted_at: "2026-09-10T00:00:00.000Z" } }
}

